func hasCycle<T: Equatable>(_ array: [T]) -> Bool {
    \/\/ Create a set to store visited elements
    var visited: Set<T> = []

    \/\/ Iterate over the array
    for element in array {
        \/\/ Check if the element has already been visited
        if visited.contains(element) {
            \/\/ If so, return true to indicate a cycle
            return true
        }

        \/\/ If not, add the element to the visited set
        visited.insert(element)
    }

    \/\/ If no cycles were found, return false
    return false
}
```

